create table if not exists public.safari_sightings(id text primary key,species text not null,latitude double precision not null,longitude double precision not null,vehicle_band text not null check(vehicle_band in ('1-3','4-6','7-10','10+')),guide_name text not null,status text not null default 'active' check(status in ('active','gone')),confirmations integer not null default 1 check(confirmations>=1),reported_at timestamptz not null default now(),updated_at timestamptz not null default now());alter table public.safari_sightings enable row level security;revoke all on table public.safari_sightings from anon, authenticated;comment on table public.safari_sightings is 'Server-only FixedRider Safari Intelligence pilot sightings.';